import java.util.*;
import java.io.*;

public class Main {
    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        int n = Integer.parseInt(br.readLine().trim());

        String[] aStr = br.readLine().trim().split(" ");
        String[] bStr = br.readLine().trim().split(" ");

        int[] playerA = new int[3];
        int[] playerB = new int[3];

        for (int i = 0; i < 3; i++) {
            playerA[i] = Integer.parseInt(aStr[i]);
            playerB[i] = Integer.parseInt(bStr[i]);
        }

        int[] playerA_orig = playerA.clone();
        int[] playerB_orig = playerB.clone();

        int maxWinScore = maxWinScore(playerA, playerB);
        int maxLossScore = maxLossScore(playerA_orig, playerB_orig);

        System.out.println((n - maxLossScore) + " " + maxWinScore);
    }

    static int maxWinScore(int[] a, int[] b) {
        int totalWins = 0;
        for (int i = 0; i < 3; i++) {
            int counter = (i + 1) % 3;
            int wins = Math.min(a[i], b[counter]);
            a[i] -= wins;
            b[counter] -= wins;
            totalWins += wins;
        }
        return totalWins;
    }

    static int maxLossScore(int[] a, int[] b) {
        int[][] movePairs = { {0, 2}, {1, 0}, {2, 1}, {0, 0}, {1, 1}, {2, 2} };
        List<int[][]> allPerms = generatePermutations(movePairs);
        int maxLoss = 0;

        for (int[][] perm : allPerms) {
            int[] aCopy = a.clone();
            int[] bCopy = b.clone();
            int[] losses = {0, 0, 0};
            for (int[] move : perm) {
                int lossAmount = Math.min(aCopy[move[0]], bCopy[move[1]]);
                aCopy[move[0]] -= lossAmount;
                bCopy[move[1]] -= lossAmount;
                losses[move[0]] += lossAmount;
            }
            int totalLoss = losses[0] + losses[1] + losses[2];
            if (totalLoss > maxLoss) {
                maxLoss = totalLoss;
            }
        }
        return maxLoss;
    }

    static List<int[][]> generatePermutations(int[][] movePairs) {
        List<int[][]> permutations = new ArrayList<>();
        permute(movePairs, 0, permutations);
        return permutations;
    }

    static void permute(int[][] arr, int index, List<int[][]> permutations) {
        if (index == arr.length - 1) {
            int[][] perm = new int[arr.length][2];
            for (int i = 0; i < arr.length; i++) {
                perm[i][0] = arr[i][0];
                perm[i][1] = arr[i][1];
            }
            permutations.add(perm);
            return;
        }
        for (int i = index; i < arr.length; i++) {
            swap(arr, i, index);
            permute(arr, index + 1, permutations);
            swap(arr, i, index);
        }
    }

    static void swap(int[][] arr, int i, int j) {
        int[] temp = arr[i];
        arr[i] = arr[j];
        arr[j] = temp;
    }
}
